  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this analysis — for example, maximizing total export revenue, maximizing net trade balance (exports minus imports), or maximizing some other measure of economic welfare?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting examples but requiring one specific answer."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "How exactly is domestic GDP defined here — is it the total value of all four goods produced (steel, engines, electronics, plastic) at their world-market prices, or is it production value minus the value of imported goods used as inputs?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive definitions of domestic GDP, so it counts as one independent question."
}

